-- Course batches and time slots (docs/designs/course-batches/course-batches.md, WF-X19, R-155): a centre's batches
-- (DD-1) and one batch per ACTIVE registration (DD-3), guarded in the database for every writer (G3). The DDL down to the
-- foreign keys was generated by prisma migrate diff.

-- AlterTable
ALTER TABLE "app"."registration" ADD COLUMN     "batch_id" INTEGER;

-- CreateTable
CREATE TABLE "app"."batch" (
    "id" SERIAL NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "starts_at" TIME NOT NULL,
    "ends_at" TIME NOT NULL,
    "capacity" INTEGER NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "batch_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "batch_centre_id_code_key" ON "app"."batch"("centre_id", "code");

-- CreateIndex
CREATE UNIQUE INDEX "batch_id_centre_id_key" ON "app"."batch"("id", "centre_id");

-- CreateIndex
CREATE INDEX "registration_batch_id_idx" ON "app"."registration"("batch_id");

-- AddForeignKey
ALTER TABLE "app"."registration" ADD CONSTRAINT "registration_batch_fkey" FOREIGN KEY ("batch_id", "centre_id") REFERENCES "app"."batch"("id", "centre_id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."batch" ADD CONSTRAINT "batch_centre_id_fkey" FOREIGN KEY ("centre_id") REFERENCES "app"."centre"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- ---------- Named checks (mirrored in src/server/batches.ts) ----------
alter table app.batch add constraint batch_code_check check (code ~ '^[!-~]+( [!-~]+)*$' and code = upper(code) and length(code) <= 30);
alter table app.batch add constraint batch_name_check check (name = btrim(name) and char_length(name) between 1 and 100);
alter table app.batch add constraint batch_time_check check (ends_at > starts_at
  and date_trunc('minute', starts_at) = starts_at and date_trunc('minute', ends_at) = ends_at);
alter table app.batch add constraint batch_capacity_check check (capacity between 1 and 500); -- PMC

-- ---------- RLS: student.view reads, batch.manage writes, at the batch's centre; no deletes ----------
alter table app.batch enable row level security;
alter table app.batch force row level security;
create policy batch_select on app.batch for select using (centre_id = any ((select app.scoped_centre_ids('student.view'))::int[]));
create policy batch_insert on app.batch for insert with check (centre_id = any ((select app.scoped_centre_ids('batch.manage'))::int[]));
create policy batch_update on app.batch for update using (centre_id = any ((select app.scoped_centre_ids('batch.manage'))::int[]))
  with check (centre_id = any ((select app.scoped_centre_ids('batch.manage'))::int[]));
create policy batch_delete on app.batch for delete using (false); -- for T-RLS-002's four commands; no delete grant

-- ---------- The placement guard (G3): one trigger on registration ----------
-- 1. Permission (the 0020 centre_write_guard shape): the app role sets or changes batch_id only with batch.manage at the
--    row's centre; this also closes inserts. 2. Rules for every role: a batch only on an ACTIVE registration, only an
--    active batch, and no placement beyond capacity. The batch row lock serialises every writer; VOLATILE (the default),
--    so the count after the lock sees what a concurrent writer committed. Invoker rights: a writer sees every row of the
--    batch's centre (the composite key keeps them there). Messages carry the name: the driver drops error.constraint.
create function app.registration_batch_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare
  changed boolean;
  b record;
  n int;
begin
  changed := case when tg_op = 'INSERT' then new.batch_id is not null else new.batch_id is distinct from old.batch_id end;
  -- nested, not AND-ed: SQL does not short-circuit, and the migration role may not execute has_permission
  if changed and current_user = 'gems_app' then
    if not app.has_permission('batch.manage', new.centre_id) then
      raise exception 'batch needs batch.manage' using errcode = '42501';
    end if;
  end if;
  if new.batch_id is null then return new; end if;
  if new.status <> 'ACTIVE' then
    if changed then
      raise exception 'registration not active: constraint "batch_registration_guard"' using errcode = '23514', constraint = 'batch_registration_guard';
    end if;
    return new;
  end if;
  -- counted anew: placed now, back to ACTIVE, or moved centre
  if not (changed or old.status <> 'ACTIVE' or old.centre_id <> new.centre_id) then return new; end if;
  select active, capacity into b from app.batch where id = new.batch_id for no key update;
  if not found or (changed and not b.active) then
    raise exception 'batch inactive or unknown: constraint "batch_active_guard"' using errcode = '23514', constraint = 'batch_active_guard';
  end if;
  select count(*) into n from app.registration where batch_id = new.batch_id and status = 'ACTIVE' and id <> new.id;
  if n >= b.capacity then
    raise exception 'batch full: constraint "batch_capacity_guard"' using errcode = '23514', constraint = 'batch_capacity_guard';
  end if;
  return new;
end $$;
create trigger registration_batch_guard before insert or update of batch_id, status, centre_id on app.registration
  for each row execute function app.registration_batch_guard();

-- ---------- Permission; the system administrator holds every permission (0013) ----------
insert into app.permission (key, description, sensitive) values
  ('batch.manage', 'Create batches and place learners in them', false)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select id, 'batch.manage' from app.role where key = 'system_admin'
on conflict do nothing;

-- ---------- Grants (codes and centres never change; batches are never deleted) ----------
grant select, insert (id, centre_id, code, name, starts_at, ends_at, capacity),
  update (name, starts_at, ends_at, capacity, active) on app.batch to gems_app;
grant usage on sequence app.batch_id_seq to gems_app;
grant update (batch_id) on app.registration to gems_app;
